-- Migration 739: National US House Representatives (Tier 1 seeding)
--
-- Seeds 299 currently-unseeded US House reps (politician + office records),
-- FK-linked to existing essentials.districts NATIONAL_LOWER rows via tiger_geoid.
-- Source: unitedstates/congress-legislators legislators-current.yaml
-- Generated by backend/scripts/seed-national-house-reps.ts
--
-- MATCHED reps only — genuine vacancies are intentionally excluded (no current member).
-- party normalized Democrat->Democratic (v2.6 SACC-03). external_id = -(state_fips*1000 + cd).
-- external_id range in this batch: -56000..-1001.
-- Shared US House chamber UUID: c2facc31-7b13-428c-b7b9-32d0d3b95f76
-- Idempotent: ON CONFLICT (external_id) DO NOTHING + NOT EXISTS (district_id, chamber_id) guard.

BEGIN;

-- Pre-flight assertions
DO $$
DECLARE
  v_chamber INT;
  v_total INT;
  v_unseeded INT;
BEGIN
  SELECT COUNT(*) INTO v_chamber FROM essentials.chambers
   WHERE id = 'c2facc31-7b13-428c-b7b9-32d0d3b95f76' AND name = 'U.S. House of Representatives';
  IF v_chamber != 1 THEN
    RAISE EXCEPTION 'Pre-flight FAILED: US House chamber c2facc31-7b13-428c-b7b9-32d0d3b95f76 not found exactly once (got %)', v_chamber;
  END IF;

  -- Guard against orphan politicians: districts MUST be loaded (Phase 116) before seeding.
  -- Checks total (not unseeded) so a re-run after a successful apply is still a clean no-op.
  SELECT COUNT(*) INTO v_total FROM essentials.districts WHERE district_type = 'NATIONAL_LOWER';
  IF v_total < 435 THEN
    RAISE EXCEPTION 'Pre-flight FAILED: only % NATIONAL_LOWER districts loaded (need >= 435; run Phase 116 first)', v_total;
  END IF;

  SELECT COUNT(*) INTO v_unseeded
  FROM essentials.districts d
  LEFT JOIN essentials.offices o ON o.district_id = d.id
  WHERE d.district_type = 'NATIONAL_LOWER' AND o.politician_id IS NULL;

  RAISE NOTICE 'Pre-flight passed: chamber=%, total NATIONAL_LOWER districts=%, unseeded=% (re-run safe via ON CONFLICT + NOT EXISTS)', v_chamber, v_total, v_unseeded;
END $$;


-- ----- AL-1: Barry Moore (Republican) — bioguide M001212, tiger_geoid '0101', external_id -1001 -----
WITH ins_p AS (
  INSERT INTO essentials.politicians
    (id, full_name, first_name, last_name, party, is_active, is_appointed,
     is_vacant, is_incumbent, external_id)
  VALUES (gen_random_uuid(), 'Barry Moore', 'Barry', 'Moore', 'Republican',
          true, false, false, true, -1001)
  ON CONFLICT (external_id) DO NOTHING
  RETURNING id
)
INSERT INTO essentials.offices
  (id, district_id, chamber_id, politician_id, title, representing_state,
   is_appointed_position, is_vacant, role_canonical)
SELECT gen_random_uuid(), d.id, 'c2facc31-7b13-428c-b7b9-32d0d3b95f76', p.id,
       'U.S. Representative', 'AL', false, false, NULL
FROM essentials.districts d
CROSS JOIN ins_p p
WHERE d.tiger_geoid = '0101' AND d.district_type = 'NATIONAL_LOWER'
  AND p.id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM essentials.offices o
    WHERE o.district_id = d.id AND o.chamber_id = 'c2facc31-7b13-428c-b7b9-32d0d3b95f76'
  );


